:host {
  --lab-canvas: #f3f5f7;
  --lab-paper: #fbfbfd;
  --lab-surface: #ffffff;
  --lab-control: #ffffff;
  --lab-ink: #1d1d1f;
  --lab-muted: #6e6e73;
  --lab-line: #d2d2d7;
  --lab-line-strong: #a7a7ad;
  --lab-accent: #5277b8;
  --lab-accent-soft: #eef2fa;
  --lab-good: #18794e;
  --lab-good-soft: #edf8f1;
  --lab-warn: #946200;
  --lab-warn-soft: #fff6e7;
  --lab-bad: #b42318;
  --lab-bad-soft: #fff0ee;
  --lab-focus: #1d1d1f;
  --lab-focus-soft: rgba(29, 29, 31, 0.18);
  --lab-font-sans: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Helvetica Neue", Arial, sans-serif;
  --lab-panel-radius: 12px;
  --lab-control-radius: 8px;
  --lab-pill-radius: 999px;
  --lab-control-height: 35px;
  --lab-panel-shadow: 0 1px 2px rgba(29, 29, 31, 0.04);
  --lab-header-max-width: 1200px;
  --lab-header-gutter: max(28px, calc((100vw - var(--lab-header-max-width)) / 2));
  --lab-page-gutter: var(--lab-header-gutter);
  --lab-compact-workspace-max: 820px;
  --lab-ink-secondary: #424245;
  --lab-surface-muted: #f7f8fa;
  --lab-line-subtle: #e7e8eb;
  --lab-accent-hover: #4569aa;
  --lab-accent-pressed: #3a5d99;
  --lab-accent-surface: #f8fbff;
  --lab-accent-line: #9fb4d6;
  --lab-accent-ink: #315b91;
  --lab-on-accent: #ffffff;
  --lab-needed: #946200;
  --lab-needed-ink: #735100;
  --lab-needed-line: #d8c36a;
  --lab-needed-soft: #fff9db;
  --lab-needed-surface: #fffdf4;
  --lab-good-ink: #225f43;
  --lab-good-line: #9cc7aa;
  --lab-good-surface: #f7fcf8;
  --lab-bad-ink: #8f2f27;
  --lab-bad-line: #d99b93;
  --lab-bad-surface: #fff8f7;
  --lab-type-body: 14px;
  --lab-type-label: 12px;
  --lab-type-annotation: 11px;
  --lab-leading-body: 1.5;
  --lab-action-height: 40px;
  --lab-target-min: 44px;
  --lab-concept-rose: #b85f52;
  --lab-concept-rose-soft: #fff1ef;
  --lab-concept-rose-ink: #8f4439;
  --lab-concept-slate-ink: #34454f;
  --lab-concept-violet: #7563a7;
  --lab-concept-amber: #c9782c;
  --lab-concept-amber-soft: #fff2e6;
  --lab-concept-amber-line: #e0b383;
  --lab-concept-amber-ink: #95571f;
  --lab-drag-halo: drop-shadow(0 0 5px rgba(82, 119, 184, 0.90)) drop-shadow(0 0 10px rgba(82, 119, 184, 0.35));
  --lab-cue-surface: rgba(250, 252, 255, 0.98);
  --lab-cue-copy: #5f7184;
  --lab-shadow-cue: 0 10px 24px rgba(29, 29, 31, 0.16);
  --lab-shadow-phase: 0 12px 30px rgba(29, 29, 31, 0.16);
  --lab-phase-good-surface: rgba(247, 252, 248, 0.99);
}

:host,
:host {
  background: var(--lab-canvas);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

:host {
  -moz-osx-font-smoothing: grayscale;
  -webkit-font-smoothing: antialiased;
  align-content: start !important;
  font-family: var(--lab-font-sans);
  margin: 0;
  padding-bottom: 0;
  padding-top: 0 !important;
  text-rendering: optimizeLegibility;
}

html[data-theme="dark"],
html[data-theme="dark"] :host {
  background: var(--bg);
}

body[data-lab-layout="compact"] [data-lab-workspace] {
  margin-left: auto;
  margin-right: auto;
  width: min(var(--lab-compact-workspace-max), 100%);
}

:where(button, input, select, textarea, summary):focus-visible {
  outline: 3px solid var(--lab-focus);
  outline-offset: 4px;
}


:host {
  --ink: var(--lab-ink);
  --muted: var(--lab-muted);
  --line: var(--lab-line);
  --accent: var(--lab-accent);
  --accent-soft: var(--lab-accent-soft);
  --good: var(--lab-good);
  --good-soft: var(--lab-good-soft);
  --warn: var(--lab-warn);
  --warn-soft: var(--lab-warn-soft);
  --bad: var(--lab-bad);
  --bad-soft: var(--lab-bad-soft);
  --water: #e8f4f8;
  --water-deep: #89bdd0;
  --wave: #2f789f;
  --wave-soft: #d7edf5;
  --barrier: #56636c;
  --barrier-edge: #38434a;
  --reference: #b7762a;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }
:host { margin: 0; color: var(--ink); background: var(--lab-canvas); }
button, input { font: inherit; }
button { cursor: pointer; }
button:disabled, input:disabled { cursor: not-allowed; opacity: .48; }
.ui-button.good { border-color: var(--good); background: var(--good); color: #fff; }
.stage-frame { position: relative; width: 100%; min-width: 680px; aspect-ratio: 900 / 430; overflow: hidden; background: var(--water); }
#home-diffraction-waveCanvas, #home-diffraction-overlay { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
#home-diffraction-waveCanvas { background: var(--water); }
#home-diffraction-overlay { user-select: none; touch-action: none; }
#home-diffraction-overlay text { font-family: var(--lab-font-sans); }
.tank-outline { fill: none; stroke: #789ba9; stroke-width: 2; }
.tank-shine { fill: none; stroke: rgba(255,255,255,.72); stroke-width: 2; }
.barrier { fill: var(--barrier); stroke: var(--barrier-edge); stroke-width: 2; }
.barrier-stripe { stroke: rgba(255,255,255,.22); stroke-width: 2; }
.gap-edge { stroke: #f5c05b; stroke-width: 4; stroke-linecap: round; }
.gap-handle { fill: #fff; stroke: #2c5f7d; stroke-width: 3; cursor: ns-resize; }
.gap-handle-halo { fill: rgba(255,255,255,.74); stroke: rgba(47,120,159,.33); stroke-width: 2; cursor: ns-resize; }
.gap-handle.locked, .gap-handle-halo.locked { cursor: not-allowed; opacity: .45; }
.lambda-line, .lambda-cap { stroke: #225f82; stroke-width: 2; }
.lambda-line.outgoing, .lambda-cap.outgoing { stroke: #4d7890; }
.lambda-handle { fill: #fff; stroke: #225f82; stroke-width: 3; cursor: ew-resize; }
.lambda-handle-halo { fill: rgba(255,255,255,.78); stroke: rgba(34,95,130,.3); stroke-width: 2; cursor: ew-resize; }
.lambda-handle.locked, .lambda-handle-halo.locked { cursor: not-allowed; opacity: .45; }
.measure-label { fill: #244f67; font-size: 11px; font-weight: 850; }
.measure-note { fill: #55707e; font-size: 9px; font-weight: 720; }
.gap-label-bg { fill: rgba(42,67,79,.86); stroke: rgba(255,255,255,.55); stroke-width: 1; }
.gap-label { fill: #fff; font-size: 9px; font-weight: 850; text-anchor: middle; }
.fan-fill { fill: rgba(82,119,184,.09); }
.fan-edge { fill: none; stroke: rgba(54,91,136,.78); stroke-width: 2; stroke-dasharray: 7 6; }
.fan-arc { fill: none; stroke: rgba(54,91,136,.88); stroke-width: 3; }
.reference-fill { fill: rgba(183,118,42,.075); }
.reference-edge { fill: none; stroke: #a85d17; stroke-width: 3; stroke-dasharray: 6 5; opacity: 1; }
.reference-arc { fill: none; stroke: #a85d17; stroke-width: 3; stroke-dasharray: 5 4; }
.direction { fill: none; stroke: #456a7d; stroke-width: 2; marker-end: url(#home-diffraction-arrowHead); }
.direction-label { fill: #385b6c; font-size: 9px; font-weight: 800; }
.stage-pill { fill: rgba(255,255,255,.9); stroke: rgba(80,112,128,.35); stroke-width: 1; }
.stage-pill-text { fill: #385661; font-size: 9px; font-weight: 800; }
.guide-card {
  position: absolute;
  z-index: 8;
  width: 215px;
  padding: 8px 9px;
  border: 1px solid #8faed1;
  border-radius: 9px;
  background: rgba(250,252,255,.97);
  box-shadow: 0 8px 18px rgba(29,29,31,.13);
  pointer-events: none;
}
.guide-card strong { display: block; color: #2f557f; font-size: 10px; line-height: 1.25; }
.guide-card span { display: block; margin-top: 2px; color: #5f7184; font-size: 8px; line-height: 1.3; }
.guide-gap { left: 33.5%; top: 36%; }
.guide-wave { left: 8%; top: 19%; }
@keyframes guidePulse { to { filter: drop-shadow(0 0 11px rgba(82,119,184,.65)); } }
.result-card.good, .feedback-card.good { border-color: #a9ceb5; background: var(--good-soft); color: #245f42; }
.working-switch button.active { background: #fff; color: #3f5360; box-shadow: 0 1px 3px rgba(29,29,31,.12); }
:host, :host { max-width: 100%; overflow-x: hidden; }
.stage-frame { min-width: 0; width: 100%; }
:host,:host{width:100%;height:100%;overflow:hidden}
.stage-frame{width:100%;min-width:0;aspect-ratio:900/420;overflow:hidden}
.measure-label{font-size:14px}
.measure-note{font-size:11px}
.gap-label{font-size:11px}
.direction-label{font-size:11px}
.stage-pill-text{font-size:10.5px}
.guide-card{width:225px;padding:9px 10px}
.guide-card strong{font-size:12px;line-height:1.25}
.guide-card span{font-size:10px;line-height:1.3}


:host {
  --lab-kit-ink: var(--lab-ink, #20303a);
  --lab-kit-muted: var(--lab-muted, #687780);
  --lab-kit-line: var(--lab-line, #cbd6dc);
  --lab-kit-surface: var(--lab-surface, #ffffff);
  --lab-kit-panel: var(--lab-paper, #f6f9fb);
  --lab-kit-accent: var(--lab-accent, #2b7ac3);
  --lab-kit-accent-soft: var(--lab-accent-soft, #e9f3fb);
  --lab-kit-good: var(--lab-good, #23794d);
  --lab-kit-good-soft: var(--lab-good-soft, #e9f7ef);
  --lab-kit-warn: var(--lab-warn, #8b6419);
  --lab-kit-warn-soft: var(--lab-warn-soft, #fff7d9);
  --lab-kit-bad: var(--lab-bad, #a3443d);
  --lab-kit-bad-soft: var(--lab-bad-soft, #fff0ef);
  --lab-kit-focus: var(--lab-focus, #1f6fb4);
  --lab-kit-focus-ring: rgba(31, 111, 180, .28);
  --lab-kit-canvas: var(--lab-paper, #fbfbfd);
  --lab-kit-canvas-grid: #e7ebee;
  --lab-kit-canvas-grid-size: 24px;
  --lab-kit-radius: var(--lab-panel-radius, 12px);
  --lab-kit-control-radius: var(--lab-control-radius, 8px);
  --lab-kit-shadow: var(--lab-panel-shadow, 0 5px 16px rgba(32, 48, 58, .08));
}
[data-lab-kit-focus]:focus-visible {
  outline: 3px solid var(--lab-kit-focus-ring);
  outline-offset: 2px;
}
.lab-activity-bar .run-actions>button.active{background:var(--lab-accent-hover,#4569aa);border-color:var(--lab-accent-hover,#4569aa);color:#fff}
@keyframes workingAttention{0%,100%{outline:2px solid var(--lab-work-attention,var(--lab-needed,#946200));outline-offset:3px;box-shadow:0 0 0 4px color-mix(in srgb,var(--lab-work-attention,var(--lab-needed,#946200)) 10%,transparent)}50%{outline:2px solid var(--lab-work-attention,var(--lab-needed,#946200));outline-offset:3px;box-shadow:0 0 0 9px color-mix(in srgb,var(--lab-work-attention,var(--lab-needed,#946200)) 22%,transparent)}}
@keyframes labGuideAttention{0%,100%{box-shadow:0 0 0 4px rgba(82,119,184,.10)}50%{box-shadow:0 0 0 9px rgba(82,119,184,.22)}}
:is(input,textarea,select):focus{outline:none!important;box-shadow:none!important;border-color:var(--lab-field-focus,var(--lab-line-strong,#a7a7ad))!important}
:is(input.good,input.correct){--lab-field-focus:var(--lab-good-ink,#225f43)}
.lab-adopt-v3{color:var(--lab-ink,#1d1d1f)}
.lab-adopt-v3 .panel{border:1px solid var(--lab-line,#d2d2d7);border-radius:12px;background:var(--lab-surface,#fff);box-shadow:none}
.lab-adopt-v3 :is(.mission).lab-activity-bar{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:16px 24px;padding:20px 24px;margin:0;border-bottom-color:var(--lab-line-subtle,#e7e8eb);border-radius:12px 12px 0 0;background:#fff}
.lab-adopt-v3 .lab-activity-bar :is(.mission-copy){flex:1 1 300px;min-width:0}
.lab-adopt-v3 .lab-activity-bar :is(.mission-copy)>strong{display:block;font-size:16px;font-weight:400;line-height:1.5;color:var(--lab-accent-ink,#315b91);letter-spacing:normal;text-wrap:balance}
.lab-adopt-v3 .lab-activity-bar :is(.mission-copy)>span{font-size:12px;font-weight:400;line-height:1.45;color:var(--lab-ink-secondary,#424245)}
.lab-adopt-v3 :is(.mission-tools){display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin-left:auto}
.lab-adopt-v3 :is(.ownership){display:flex;align-items:center;gap:8px;background:transparent;border:0;padding:0;box-shadow:none}
.lab-adopt-v3 :is(.ownership>span){color:var(--lab-ink,#1d1d1f);font-size:14px;font-weight:400;white-space:nowrap}
.lab-adopt-v3 .lab-activity-bar .lab-toggle{display:inline-flex;flex:none;padding:3px;border:1px solid var(--lab-line,#d2d2d7);border-radius:999px;background:var(--lab-surface-muted,#f7f8fa);box-shadow:0 1px 3px rgba(29,29,31,.08);height:42px;gap:2px}
.lab-adopt-v3 .lab-activity-bar .lab-toggle>button{width:auto;min-height:34px;min-width:40px;padding:0 12px;border:1px solid transparent;border-radius:999px;background:transparent;color:var(--lab-ink-secondary,#424245);font:400 12px/1.2 var(--lab-font-sans,sans-serif);box-shadow:none}
.lab-adopt-v3 .lab-activity-bar .lab-toggle>button[aria-pressed="true"]{background:var(--lab-ink-secondary,#424245);color:#fff}
.lab-adopt-v3 .lab-activity-bar .lab-toggle[data-kind="mode"]>button[aria-pressed="true"]{background:var(--lab-accent-hover,#4569aa);color:#fff}
.lab-adopt-v3 .lab-activity-bar+:is(.lab,.workbench){margin-top:0;border-top:0;border-radius:0 0 12px 12px;padding:20px 24px;position:relative}
.lab-adopt-v3:not(.lab-computing) :is(.workspace){display:grid;grid-template-columns:minmax(0,1fr) minmax(280px,320px);gap:24px;align-items:start}
.lab-adopt-v3 .calc-step::before{display:none}
.lab-adopt-v3 :is(.calc-step,.solve-card,.derive-step){padding:12px;border:1px solid var(--lab-line-subtle,#e7e8eb);border-radius:8px;background:var(--lab-surface-muted,#f7f8fa);box-shadow:none;opacity:1}
.lab-adopt-v3 :is(.calc-step,.solve-card,.derive-step):has(input:not(:disabled)){border-color:var(--lab-needed-line,#d8c36a);background:var(--lab-needed-surface,#fffdf4)}
.lab-adopt-v3 :is(.calc-step,.solve-card,.derive-step):has(input):is(.good,.complete,.correct),.lab-adopt-v3 :is(.calc-step,.solve-card,.derive-step):has(input.good):not(:has(input:not(.good))){border-color:var(--lab-good-line,#9cc7aa);background:var(--lab-good-surface,#f7fcf8)}
.lab-adopt-v3 :is(.calc-step,.solve-card,.derive-step):has(input):is(.bad,.incorrect),.lab-adopt-v3 :is(.calc-step,.solve-card,.derive-step):has(input.bad,input.incorrect){border-color:var(--lab-bad-line,#d8aaa4);background:var(--lab-bad-surface,#fff8f7)}
.lab-adopt-v3 :is(.calc-step,.solve-card,.derive-step):has(input:not(:disabled)):not(.good,.complete,.correct,.bad,.incorrect):not(:has(input.bad,input.incorrect)):not([data-interacted="true"]){animation:workingAttention 2s ease-in-out infinite}
.lab-adopt-v3 :is(.calc-step,.solve-card,.derive-step):has(input)::after{display:none}
.lab-adopt-v3 :is(.step-head span,.solve-card>span,.derive-step-head strong){font-size:12px;line-height:1.45;font-weight:400;text-transform:none;letter-spacing:normal;color:var(--lab-ink-secondary,#424245)}
.lab-adopt-v3 :is(.solve-card>strong):not(:has(input)){width:fit-content;max-width:100%;padding:3px 7px;border:0;border-radius:4px;background:color-mix(in srgb,var(--lab-concept-violet,#7563a7) 20%,white);color:var(--lab-ink,#1d1d1f);font-size:14px;font-weight:400;line-height:1.45;box-shadow:none;overflow-wrap:anywhere}
.lab-adopt-v3 input:not([type="range"]):not([type="checkbox"]):not([type="radio"]){min-height:40px;padding:6px 9px;border-width:1px;border-radius:8px;font-size:14px;font-weight:400;line-height:1.4}
.lab-adopt-v3 :is(input.good,input.correct){border-color:var(--lab-good-line,#9cc7aa);background:var(--lab-good-surface,#f7fcf8)}
.lab-adopt-v3 :is(input.bad,input.incorrect){border-color:var(--lab-bad-line,#d8aaa4);background:var(--lab-bad-surface,#fff8f7)}
.lab-adopt-v3 :is(.visual-copy span){font-size:12px;font-weight:400;line-height:1.45}
.lab-adopt-v3 .lab-action{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:8px 14px;border:1px solid var(--lab-accent-line,#9fb4d6);border-radius:8px;background:#fff;color:var(--lab-accent-ink,#315b91);font-size:12px;font-weight:400;line-height:1.3;box-shadow:0 1px 3px rgba(29,29,31,.08)}
.lab-adopt-v3 .lab-action[data-priority="primary"]{background:var(--lab-accent-hover,#4569aa);border-color:var(--lab-accent-pressed,#3a5d99);color:#fff}
.lab-adopt-v3 .lab-action:disabled{background:var(--lab-surface-strong,#eef1f3);color:var(--lab-muted,#6e6e73);border-color:var(--lab-line,#d2d2d7);box-shadow:none;opacity:1}
.lab-adopt-v3 .next-card{position:absolute;top:16px;right:16px;bottom:auto;left:auto;width:min(320px,calc(100% - 32px));max-width:none;padding:16px;border:1px solid var(--lab-good-line,#9cc7aa);border-radius:12px;background:var(--lab-good-surface,#f7fcf8);box-shadow:0 6px 18px rgba(29,29,31,.12);z-index:30;transform:none}
.lab-adopt-v3 .next-card>strong{display:block;padding-right:30px;color:var(--lab-ink,#1d1d1f);font-size:14px;font-weight:500;line-height:1.4}
.lab-adopt-v3 .next-card span{font-size:14px;line-height:1.45;font-weight:400}
.lab-adopt-v3 .next-card .next-actions{display:flex;justify-content:center;gap:8px}
.lab-adopt-v3 .next-card button:not(.lab-dialog-move){min-height:40px;padding:10px 18px;font-size:11px;font-weight:600;border-radius:8px}
.lab-adopt-v3 .next-card .lab-dialog-move{position:absolute;top:6px;right:6px;width:32px;min-width:32px;height:32px;min-height:32px;margin:0;padding:0;border:0;border-radius:8px;background:transparent;color:var(--lab-muted,#6e6e73);cursor:grab;touch-action:none;font-size:16px;font-weight:400}
.lab-adopt-v3 .next-card .lab-dialog-move:active{cursor:grabbing}

.lab-adopt-v3 :is(.mission-tools)>button{order:-1}
.lab-adopt-v3 .lab-activity-bar>.complexity{margin-left:auto}
.lab-adopt-v3 .next-card.has-upgrade{display:block}
.lab-adopt-v3 .next-card .next-upgrade{margin-top:12px;padding-top:12px;border:0;border-top:1px solid var(--lab-line-subtle,#e7e8eb);background:transparent}

.lab-adopt-v3 .next-card[hidden]{display:none!important}
.lab-adopt-v3 :is(.stage-shell,.stage){background:transparent;border:0;border-radius:0}
.lab-adopt-v3 :is(.ownership>span){font:400 12px/1.4 var(--lab-font-sans,sans-serif);text-transform:none;letter-spacing:normal}
.lab-adopt-v3 [hidden]{display:none!important}
.lab-adopt-v3 :is(.solve-card){font-family:var(--lab-font-sans,sans-serif);font-weight:400}
.lab-adopt-v3 :is(.lab-work-card p){font:400 14px/1.45 var(--lab-font-sans,sans-serif)}
.lab-adopt-v3 .next-card .lab-dialog-move{display:grid;place-items:center}
.lab-adopt-v3 .visual-head{padding:0 0 12px;border:0;gap:12px}
.lab-adopt-v3 .visual-copy strong{font-size:14px;font-weight:500}
.lab-adopt-v3 .lab-checkpoint{width:12px;min-width:12px;height:12px;min-height:12px;padding:0;border:1px solid var(--lab-line-strong,#a7a7ad);border-radius:50%;background:#fff;opacity:1;box-shadow:none}
.lab-adopt-v3 .lab-checkpoint[aria-current="true"]{border-color:var(--lab-accent,#5277b8);box-shadow:inset 0 0 0 3px #fff;background:var(--lab-accent,#5277b8)}
.lab-adopt-v3 .lab-checkpoint[data-complete="true"]{border-color:var(--lab-good,#18794e);background:var(--lab-good,#18794e)}
.lab-adopt-v3 .visual-head:has(.visual-copy[hidden]){display:flex;justify-content:flex-end}
.lab-adopt-v3 :is(.step-head>span,.derive-step-head strong,.solve-card:not(.solve-entry)>span,.lab-work-card>strong){
  font:400 15px/1.4 var(--lab-font-sans,sans-serif);color:var(--lab-ink,#1d1d1f);letter-spacing:normal;text-transform:none;margin-block:0 6px;
}
@keyframes labSvgIntroAttention{0%,100%{filter:drop-shadow(0 0 3px rgba(82,119,184,.35))}50%{filter:drop-shadow(0 0 7px rgba(82,119,184,.8))}}
.lab-adopt-v3 .lab-sidebar .relationship{padding:8px 0 0;border:0;background:transparent;box-shadow:none;border-radius:0}
.lab-adopt-v3 .lab-activity-bar #missionTitle{margin:0;font:400 16px/1.5 var(--lab-font-sans,sans-serif);color:var(--lab-accent-ink,#315b91)}
.lab-investigation button:is(.selected,.active,[aria-pressed="true"]):not(.counter){background:var(--lab-accent-soft,#eef2fa);color:var(--lab-accent-ink,#315b91)}
.lab-investigation .lab-activity-bar .lab-toggle button.active{background:var(--lab-ink-secondary,#424245);color:#fff}
.lab-investigation .lab-activity-bar .lab-toggle[data-kind="mode"] button.active{background:var(--lab-accent-hover,#4569aa);color:#fff}
.lab-investigation .lab-sidebar :is(.work-step,.working-step,.calc-step,.work-section,.evidence-section,.work-block):is(.good,.done,[data-state="correct"]){border-color:var(--lab-good-line,#9cc7aa);background:var(--lab-good-surface,#f7fcf8)}
.lab-investigation .lab-sidebar :is(input[data-state="correct"],.good input,input.good){border-color:var(--lab-good-line,#9cc7aa);background:var(--lab-good-surface,#f7fcf8)}
.lab-investigation input.good:focus-visible{border-color:var(--lab-good,#18794e)!important}
.lab-svg-value-surface{fill:color-mix(in srgb,var(--lab-concept-violet,#7563a7) 16%,white);stroke:none;pointer-events:none}
svg text[data-lab-value]{font-size:var(--lab-value-fit-size,var(--lab-value-font-size,18px))!important;font-weight:400!important;--lab-value-padding-x:7;--lab-value-padding-y:3}
@supports (appearance:base-select){
  :is(.lab-adopt-v3,.lab-settings-adopt) select:not([multiple]):not([size]),:is(.lab-adopt-v3,.lab-settings-adopt) select:not([multiple]):not([size])::picker(select){appearance:base-select}
  :is(.lab-adopt-v3,.lab-settings-adopt) select:not([multiple]):not([size]){background-image:none;padding:8px 12px;gap:12px;align-items:center;border:1px solid var(--lab-line);border-radius:999px;background-color:var(--lab-surface);color:var(--lab-ink);font:400 12px/1.4 var(--lab-font-sans);min-height:40px;box-shadow:0 1px 3px #1d1d1f14}
  :is(.lab-adopt-v3,.lab-settings-adopt) select::picker(select){border:1px solid #1d1d1f1f;border-radius:18px;box-shadow:0 18px 50px #1d1d1f1f,0 3px 12px #1d1d1f14;background:var(--lab-surface);padding:7px;margin-block:9px;max-height:min(360px,70vh);overflow:auto;color:var(--lab-ink);font:400 14px/1.4 var(--lab-font-sans)}
  :is(.lab-adopt-v3,.lab-settings-adopt) select::picker-icon{content:"";width:7px;height:7px;border-right:1.5px solid currentColor;border-bottom:1.5px solid currentColor;color:var(--lab-muted);rotate:45deg;margin-inline:6px 2px;transition:rotate .15s}
  :is(.lab-adopt-v3,.lab-settings-adopt) select:open::picker-icon{rotate:225deg}
  :is(.lab-adopt-v3,.lab-settings-adopt) select option{border:0;border-radius:12px;min-height:42px;padding:9px 11px;background:var(--lab-surface);color:var(--lab-ink);font:400 14px/1.4 var(--lab-font-sans);cursor:pointer;gap:16px}
  :is(.lab-adopt-v3,.lab-settings-adopt) select option:is(:hover,:focus){background:var(--lab-surface-muted);outline:none}
  :is(.lab-adopt-v3,.lab-settings-adopt) select option:checked{background:var(--lab-accent-soft);color:var(--lab-accent-ink)}
  :is(.lab-adopt-v3,.lab-settings-adopt) select option::checkmark{order:2;margin-left:auto;color:var(--lab-accent)}
  :is(.lab-adopt-v3,.lab-settings-adopt) select :is(option,optgroup):disabled,:is(.lab-adopt-v3,.lab-settings-adopt) select:disabled{color:var(--lab-muted);background:var(--lab-surface-muted);cursor:default;box-shadow:none}
}
@font-face{font-family:Lab Index I;src:local('Georgia');unicode-range:U+0049;font-weight:100 900}
.lab-chip.good{background:var(--lab-good-soft);color:var(--lab-good)}
@keyframes lab-run-attention{50%{box-shadow:0 0 0 4px color-mix(in srgb,var(--lab-accent) 24%,transparent)}}
:is(.lab-adopt-v3,.lab-settings-adopt) .lab-activity-bar:has([data-lab-setting]){display:flex;align-items:center;flex-wrap:wrap;gap:16px}
:is(.lab-adopt-v3,.lab-settings-adopt) .lab-activity-bar .lab-settings-path{display:contents!important}
:is(.lab-adopt-v3,.lab-settings-adopt) .lab-setting-old-label{display:none!important}
:is(.lab-adopt-v3,.lab-settings-adopt) .lab-activity-bar [data-lab-setting]{flex:none;margin:0;align-self:center}
:is(.lab-adopt-v3,.lab-settings-adopt) .lab-activity-bar [data-lab-setting="working"]{order:30;position:relative;overflow:visible}
:is(.lab-adopt-v3,.lab-settings-adopt) .lab-activity-bar [data-lab-setting="exam"]{order:40;position:relative;overflow:visible}
:is(.lab-adopt-v3,.lab-settings-adopt) .lab-activity-bar [data-lab-setting="checkpoints"]{order:50}
:is(.lab-adopt-v3,.lab-settings-adopt) .lab-activity-bar [data-lab-setting-lead]{margin-left:auto}
:is(.lab-adopt-v3,.lab-settings-adopt) :is([data-lab-setting="working"],[data-lab-setting="exam"])::before{position:absolute;left:50%;top:-18px;transform:translateX(-50%);padding:0;border:0;background:none;color:var(--lab-ink-secondary);font:400 11px/1.2 var(--lab-font-sans,sans-serif);white-space:nowrap;pointer-events:none}
:is(.lab-adopt-v3,.lab-settings-adopt) [data-lab-setting="working"]::before{content:'Working'}
:is(.lab-adopt-v3,.lab-settings-adopt) [data-lab-setting="exam"]::before{content:'Exam'}
:is(.lab-adopt-v3,.lab-settings-adopt) .lab-activity-bar :is([data-lab-setting="working"],[data-lab-setting="exam"])>button:is([aria-pressed="true"],[aria-checked="true"]){background:var(--lab-ink,#1d1d1f);color:var(--lab-surface,#fff);font-weight:400;border-color:transparent;box-shadow:none}
:is(.lab-adopt-v3,.lab-settings-adopt) .lab-activity-bar :is([data-lab-setting="working"],[data-lab-setting="exam"])>button:disabled{cursor:default}
button[data-lab-attention="true"]:not(:disabled){animation:lab-run-attention 1.8s ease-in-out infinite}
@keyframes lab-card-attention{50%{stroke:var(--lab-accent-pressed,#3a5d99);stroke-width:3.5;filter:drop-shadow(0 0 3px color-mix(in srgb,var(--lab-accent) 35%,transparent))}}
svg rect[data-lab-attention="true"]{animation:lab-card-attention 1.8s ease-in-out infinite;stroke:var(--lab-accent)}
:is(.lab-adopt-v3,.lab-settings-adopt) .lab-activity-bar :is([data-lab-setting="working"],[data-lab-setting="exam"]){padding:3px;border:1px solid var(--lab-line,#d2d2d7);border-radius:10px;background:var(--lab-surface-muted,#f7f8fa);box-shadow:0 1px 3px rgb(29 29 31 / 8%)}
:is(.lab-adopt-v3,.lab-settings-adopt) .lab-activity-bar :is([data-lab-setting="working"],[data-lab-setting="exam"])>button{border-radius:7px;min-height:32px;padding:0 12px;font:400 12px/1.2 var(--lab-font-sans,sans-serif)}
:is(.lab-adopt-v3,.lab-settings-adopt) :is([data-lab-setting="working"],[data-lab-setting="exam"])::before{top:-20px}
:is(.lab-adopt-v3,.lab-settings-adopt) .lab-reset-action{display:inline-flex;align-items:center;justify-content:center;min-height:34px;padding:7px 12px;border:1px solid var(--lab-accent-line,#9fb4d6);border-radius:8px;background:var(--lab-surface,#fff);color:var(--lab-accent-ink,#315b91);font:400 12px/1.3 var(--lab-font-sans,sans-serif);box-shadow:0 1px 3px rgb(29 29 31 / 8%)}
:is(.lab-adopt-v3,.lab-settings-adopt) .lab-reset-action:disabled{background:var(--lab-surface-strong,#eef1f3);color:var(--lab-muted,#6e6e73);border-color:var(--lab-line,#d2d2d7);box-shadow:none;opacity:1;cursor:not-allowed}
.lab-adopt-v3 .next-card{animation:none;text-align:left}
.lab-adopt-v3 .next-card .next-actions{margin-top:14px;flex-wrap:wrap}
.lab-adopt-v3 .next-card button:not(.lab-dialog-move){font:400 12px/1.3 var(--lab-font-sans,sans-serif);padding:10px 18px;min-height:38px;border-radius:8px}
.lab-adopt-v3 .next-card .next-actions>button{background:var(--lab-accent-hover,#4569aa);border:1px solid var(--lab-accent-pressed,#3a5d99);color:#fff;box-shadow:0 1px 3px rgb(29 29 31 / 8%)}
.lab-adopt-v3 .next-card .next-actions>button::after{content:none}

.lab-adopt-v3 .next-card .next-actions>button{width:auto;flex:none}

.lab-adopt-v3 .lab-field-control input{border-color:var(--lab-needed-line,#d8c36a);background:var(--lab-needed-surface,#fffdf4)}
.lab-adopt-v3 .lab-field-control input.good{border-color:var(--lab-good-line,#9cc7aa);background:var(--lab-good-surface,#f7fcf8)}
.lab-adopt-v3 .lab-field-control input.bad{border-color:var(--lab-bad-line,#d8aaa4);background:var(--lab-bad-surface,#fff8f7)}
.lab-science .lab-activity-bar{margin-bottom:0;padding:24px;border-radius:12px 12px 0 0;border:1px solid var(--lab-line);background:var(--lab-surface);box-shadow:none}
.lab-science .lab-activity-bar .mission-tools:empty{display:none}
.lab-science :is(.problem-kicker,.mission-copy>span,.phase-track,.eyebrow,.working-title>span){display:none!important}
.lab-science .lab.panel{margin:0;border-top:0;border-radius:0 0 12px 12px;overflow:visible;min-height:0;height:auto}
.lab-science .workspace{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:0;min-height:0;height:auto;align-items:start}
.lab-science :is(.stage-shell,.stage-frame){width:100%;min-width:0;min-height:0;height:auto;max-height:none;overflow:visible;background:transparent}
.lab-science .stage-shell{position:relative}
.lab-science .stage{display:block;width:100%!important;min-width:0!important;height:auto!important;max-height:none;aspect-ratio:auto}
.lab-science .visual-head{display:flex;align-items:center;flex-wrap:wrap;gap:12px;padding:14px 16px;border:0;background:transparent;min-height:54px}
.lab-science .visual-copy{display:none}
.lab-science :is(.legend){font:400 12px/1.4 var(--lab-font-sans);letter-spacing:normal;text-transform:none}
.lab-science :is(.workbench){min-width:0;min-height:0;height:auto;max-height:none;overflow:visible;padding:16px;border:0;border-left:1px solid var(--lab-line-subtle);background:transparent;display:flex;flex-direction:column;gap:12px}
.lab-science :is(.evidence-section,.invariants,.work-step){padding:12px;border:1px solid var(--lab-line-subtle);border-radius:10px;background:var(--lab-surface-muted);box-shadow:none;min-height:0}
.lab-science :is(.work-step.current){border-color:var(--lab-needed-line);background:var(--lab-needed-surface)}
.lab-science :is(.work-step.good,.result-card.good){border-color:var(--lab-good-line);background:var(--lab-good-surface)}
.lab-science .work-step.locked{opacity:1;background:var(--lab-surface-muted);border-color:var(--lab-line-subtle)}
.lab-science .work-step.locked>:not(.step-head){display:none}
.lab-science :is(.evidence-head,.working-head){padding:0 0 10px;margin:0;border:0;background:none}
.lab-science :is(.workbench h2,.evidence-head strong,.step-head strong,.working-head strong){font:400 15px/1.4 var(--lab-font-sans);letter-spacing:normal;text-transform:none;margin:0 0 6px;color:var(--lab-ink)}
.lab-science :is(p,.coach-copy,.result-card,.feedback-card){font:400 14px/1.45 var(--lab-font-sans);letter-spacing:normal;text-transform:none}
.lab-science :is(.evidence-head>span,.model-note,.readout>span,.measure-label){font:400 11px/1.45 var(--lab-font-sans);letter-spacing:normal;text-transform:none}
.lab-science :is(.readout strong){font:400 14px/1.4 var(--lab-font-sans);letter-spacing:normal}
.lab-science :is(strong,b){font-weight:400}
.lab-science :is(.prediction-row){display:grid;grid-template-columns:1fr;gap:8px;padding:0;border:0;background:none;box-shadow:none;outline:0;animation:none}
.lab-science :is(.prediction-row)>button{display:block;min-height:40px;padding:9px 12px;text-align:left;white-space:normal;font:400 14px/1.4 var(--lab-font-sans);border:1px solid var(--lab-line);border-radius:8px;background:var(--lab-surface);color:var(--lab-ink);box-shadow:none}
.lab-science :is(.prediction-row)>button:is(.selected,[aria-pressed="true"]){background:var(--lab-accent-soft);border-color:var(--lab-accent-line)}
.lab-science :is(.coach-actions){display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}
.lab-science :is(.coach-actions)>button{white-space:normal}
.lab-science .step-head{gap:8px;margin-bottom:8px}
.lab-science :is(input[type="number"],input[type="text"]){min-height:38px;padding:7px 9px;font:400 14px/1.4 var(--lab-font-sans);border:1px solid var(--lab-needed-line);border-radius:6px;background:var(--lab-needed-surface)}
.lab-science input.good{background:var(--lab-good-surface);border-color:var(--lab-good-line)}
.lab-science input.bad{background:var(--lab-bad-surface);border-color:var(--lab-bad-line)}
.lab-science :is(.feedback.bad,.feedback-card.bad){background:var(--lab-bad-surface);border-color:var(--lab-bad-line);color:var(--lab-bad-ink)}
.lab-science :is(.feedback.good,.feedback-card.good){background:var(--lab-good-surface);border-color:var(--lab-good-line);color:var(--lab-good-ink)}
.lab-science :is(.guide-card){display:none!important}
.lab-science svg text{font-family:var(--lab-font-sans)!important;font-weight:400!important;letter-spacing:normal!important;font-size:var(--lab-chart-text-size,14px)!important;text-shadow:none!important;text-transform:none}
.lab-science .readout{padding:8px;border:0;background:var(--lab-surface-muted);border-radius:6px}
.lab-science .next-card{position:absolute!important;min-height:0;max-width:320px;z-index:30}
.science-diffraction .lab.panel{display:grid;grid-template-columns:minmax(0,1fr) 360px;grid-template-areas:'head head' 'stage work' 'controls work';align-items:start}
.science-diffraction .stage-shell{grid-area:stage}
.science-diffraction .workbench{grid-area:work}
.science-diffraction .visual-head{grid-area:head}.science-diffraction .controls{grid-area:controls;padding:12px;display:grid;grid-template-columns:1fr 1fr;gap:12px;background:none}
.science-diffraction .stage-frame{aspect-ratio:760/360}
.science-diffraction .stage-frame>canvas,.science-diffraction .stage-frame>svg{width:100%!important;height:100%!important;min-width:0!important}
.science-diffraction .prediction-map{display:none}
.science-diffraction .control-card{padding:10px;border:0;background:var(--lab-surface-muted);border-radius:8px;font-size:12px}
.science-diffraction :is(.control-card strong,.control-card span,.readouts b){font-size:12px;font-weight:400}
.science-diffraction .control-card.consequence{grid-column:1/-1}
.science-diffraction :is(.coach-copy,.action-strip,.evidence-head>span,.model-note){display:none}
.science-diffraction :is(.challenge-grid,.working-grid){grid-template-columns:1fr;gap:10px}
.science-diffraction .working-box,.science-diffraction .evidence{padding:12px;border:0;background:var(--lab-surface-muted);border-radius:8px}
.lab-science :is(.prediction-row)>button::before{display:none}
.lab-science :is(.prediction-row)>button{padding-left:12px}
.science-diffraction :is(.workbench-grid,.coach,.evidence){display:block;height:auto!important;max-height:none!important;overflow:visible;grid-template-rows:none!important}
.science-diffraction .evidence{margin-top:12px;display:block!important}
.science-diffraction .coach{padding:12px;border:1px solid var(--lab-needed-line);border-radius:10px;background:var(--lab-needed-surface)}
.science-diffraction .evidence-row{padding:10px;border:0;border-radius:6px;background:var(--lab-surface);margin-top:8px}
.science-diffraction .evidence-row strong{font:400 12px/1.4 var(--lab-font-sans)}
.science-diffraction .live-line{display:none}
.science-diffraction :is(.work-field,.target){padding:8px;border:0;border-radius:6px;background:var(--lab-surface)}
.science-diffraction :is(.work-field>span,.target strong,.target span,.working-hint){font:400 12px/1.4 var(--lab-font-sans)}
.science-diffraction .work-auto{font:400 14px/1.4 var(--lab-font-sans)}
:host:has(.lab-science),.lab-science{height:auto;overflow:visible}
.lab-adopt-v3 .lab-sequence-target{animation:workingAttention 2s ease-in-out infinite;border-color:var(--lab-needed-line)}
.lab-adopt-v3 button.lab-sequence-target:not(:disabled){animation:lab-run-attention 1.8s ease-in-out infinite;border-color:var(--lab-accent)}
.lab-adopt-v3 svg .lab-sequence-target{animation:labSvgIntroAttention 2s ease-in-out infinite}
.science-diffraction .lab.panel{grid-template-areas:'head head' 'stage work'}
.science-diffraction :is(.gap-handle,.lambda-handle){fill:white;stroke:var(--lab-accent);stroke-width:3px}
.science-diffraction :is(.gap-handle-halo,.lambda-handle-halo){fill:var(--lab-accent-soft);stroke:var(--lab-accent-line)}
.science-diffraction .gap-label-bg{fill:white;stroke:var(--lab-accent-line);stroke-width:1}
.science-diffraction .gap-label{fill:var(--lab-ink)}


:host{display:block;margin:0;background:transparent;font-size:16px} *{transition:none!important;animation-play-state:paused!important;animation-delay:calc(var(--preview-animation-time,0) * -1ms)!important}
